  // Group games by date
  const gamesByDate = {};
  games.forEach(g => {
    if (!gamesByDate[g.date]) gamesByDate[g.date] = [];
    gamesByDate[g.date].push(g);
  });

  const dates = Object.keys(gamesByDate).sort();

  // We want to pick 1 game per date, for 30 distinct teams, out of the dates available.
  // Let's use randomized greedy search with simulated annealing / restarts to find valid 30-game schedules!
  let bestSchedule = null;
  let bestScore = -Infinity;

  for (let trial = 0; trial < 20000; trial++) {
    const pickedTeams = new Set();
    const schedule = [];
    let prevCity = null;

    // Shuffle or sort dates with slight random perturbation
    for (let d = 0; d < dates.length; d++) {
      const date = dates[d];
      const available = gamesByDate[date].filter(g => !pickedTeams.has(g.homeTeam));
      if (available.length === 0) continue;

      // Score options on this date
      // We prefer: star player games (+1000), short distance from prevCity (-dist), remaining teams urgency
      const scored = available.map(g => {
        let s = 0;
        if (g.starPlayer) s += 1500;
        if (prevCity) {
          const dKm = dist(prevCity, g.arenaCity);
          s -= dKm * 0.8;
        }
        // Add random noise for exploration
        s += (Math.random() - 0.5) * 400;
        return { g, s };
      });

      scored.sort((a, b) => b.s - a.s);
      const chosen = scored[0].g;
      schedule.push(chosen);
      pickedTeams.add(chosen.homeTeam);
      prevCity = chosen.arenaCity;

      if (pickedTeams.size === 30) break;
    }

    if (pickedTeams.size === 30) {
      // Calculate total score: star count * 2000 - total distance
      let totalDist = 0;
      let starCount = 0;
      for (let i = 0; i < schedule.length; i++) {
        if (schedule[i].starPlayer) starCount++;
        if (i > 0) {
          totalDist += dist(schedule[i-1].arenaCity, schedule[i].arenaCity);
        }
      }
      const score = starCount * 3000 - totalDist;
      if (score > bestScore) {
        bestScore = score;
        bestSchedule = {
          schedule,
          starCount,
          totalDistKm: Math.round(totalDist),
          score
        };
      }
    }
  }

  return {
    found: !!bestSchedule,
    bestScore,
    bestSchedule: bestSchedule ? {
      starCount: bestSchedule.starCount,
      totalDistKm: bestSchedule.totalDistKm,
      stops: bestSchedule.schedule.map((g, idx) => ({
        stop: idx + 1,
        date: g.date,
        homeTeam: g.homeTeam,
        awayTeam: g.awayTeam,
        arena: g.arenaName,
        city: g.arenaCity,
        starPlayer: g.starPlayer,
        gameId: g.gameId,
        gameCode: g.gameCode
      }))
    } : null
  };
});

