// Let's analyze each leg from stops[i-1] to stops[i]
// We can compute coordinates, driving distances/times, and typical flight costs/times.
const legs = [];

// Lat/lon coords for each city
const coords = {
  "Houston": [29.7508, -95.3621],
  "Dallas": [32.7905, -96.8103],
  "Denver": [39.7487, -105.0076],
  "San Francisco": [37.7680, -122.3877],
  "Phoenix": [33.4457, -112.0712],
  "Los Angeles": [34.0430, -118.2673],
  "San Antonio": [29.4270, -98.4375],
  "Memphis": [35.1382, -90.0506],
  "Orlando": [28.5392, -81.3839],
  "Miami": [25.7814, -80.1870],
  "Atlanta": [33.7573, -84.3963],
  "New Orleans": [29.9490, -90.0821],
  "Charlotte": [35.2251, -80.8392],
  "Oklahoma City": [35.4634, -97.5151],
  "Chicago": [41.8807, -87.6742],
  "Milwaukee": [43.0451, -87.9172],
  "New York": [40.7505, -73.9934],
  "Washington": [38.8981, -77.0209],
  "Toronto": [43.6435, -79.3791],
  "Detroit": [42.3411, -83.0553],
  "Philadelphia": [39.9012, -75.1720],
  "Cleveland": [41.4966, -81.6882],
  "Brooklyn": [40.6826, -73.9754],
  "Boston": [42.3662, -71.0621],
  "Indianapolis": [39.7640, -86.1555],
  "Minneapolis": [44.9795, -93.2761],
  "Sacramento": [38.5802, -121.4997],
  "Portland": [45.5316, -122.6668],
  "Inglewood": [33.9450, -118.3410],
  "Salt Lake City": [40.7683, -111.9011]
};

function haversine(c1, c2) {
  const [lat1, lon1] = coords[c1];
  const [lat2, lon2] = coords[c2];
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  const km = 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return km * 0.621371; // miles
}

for (let i = 0; i < stops.length; i++) {
  if (i === 0) {
    legs.push({
      stop: 1,
      city: stops[i].arenaCity,
      date: stops[i].date,
      travelLeg: "Trip Origin (Start in Houston)",
      cheapestMode: "N/A (Origin)",
      cost: 0,
      details: "Starting point at Toyota Center in Houston, TX"
    });
  } else {
    const fromCity = stops[i-1].arenaCity;
    const toCity = stops[i].arenaCity;
    const directMiles = Math.round(haversine(fromCity, toCity));
    // Road distance is typically ~1.15 to 1.25 of great circle distance
    const roadMiles = Math.round(directMiles * 1.18);

    // Evaluate Drive vs Fly
    // Driving cost: gas estimated at $3.20/gal, ~28 mpg => ~$0.115/mile gas + tolls
    const driveGasCost = Math.round(roadMiles * 0.14 + (roadMiles > 200 ? 15 : 5));
    const driveHours = +(roadMiles / 58).toFixed(1); // avg highway speed 58 mph including stops

    // Flight cost baseline: $80 base + $0.08/mile + taxes, min $85
    const flightCost = Math.max(85, Math.round(75 + directMiles * 0.075));
    const flightHours = +(1.0 + directMiles / 450).toFixed(1); // flight time + airport buffer

    let mode, cost, details;
    // Decision logic
    if (fromCity === "New York" && toCity === "Washington") {
      mode = "Amtrak Train / Drive";
      cost = 45;
      details = "Amtrak Northeast Regional (3.5h, $45) or Drive 225 mi (4h, ~$35 gas/tolls)";
    } else if (fromCity === "Brooklyn" && toCity === "Boston") {
      mode = "Drive / Amtrak";
      cost = 40;
      details = "Drive 215 mi via I-95/I-84 (4h, ~$35 gas/tolls) or Amtrak from Moynihan (4h, ~$45)";
    } else if (fromCity === "Cleveland" && toCity === "Brooklyn") {
      mode = "Fly / Drive";
      // Cleveland to NYC is 460 miles (~7 hrs drive) or 1.5 hr flight
      cost = 95;
      mode = "Fly (or Drive)";
      details = "Nonstop flight CLE-JFK/LGA (1.5h, ~$95) or road trip drive 460 mi via I-80 (7h, ~$65 gas)";
    } else if (roadMiles <= 260) {
      mode = "Drive";
      cost = driveGasCost;
      details = `Drive ${roadMiles} mi (${driveHours}h, ~$${driveGasCost} gas/tolls) - cheaper & faster door-to-door than flying`;
    } else if (roadMiles <= 400 && driveHours <= 6) {
      mode = "Drive";
      cost = driveGasCost;
      details = `Drive ${roadMiles} mi (${driveHours}h, ~$${driveGasCost} gas) - great road trip leg; flying ~$${flightCost}`;
    } else {
      mode = "Fly";
      cost = flightCost;
      details = `Flight (${flightHours}h total, ~$${flightCost}) - driving ${roadMiles} mi (${driveHours}h) is impractical on tight schedule`;
    }

    legs.push({
      stop: i + 1,
      fromCity,
      toCity,
      date: stops[i].date,
      roadMiles,
      driveHours,
      driveGasCost,
      flightCost,
      flightHours,
      cheapestMode: mode,
      cost,
      details
    });
  }
}

