        if (starTeam === 'LAL') starPlayer = "LeBron James (LAL)";
        else if (starTeam === 'GSW') starPlayer = "Stephen Curry (GSW)";
        else if (starTeam === 'SAS') starPlayer = "Victor Wembanyama (SAS)";

        games.push({
          gameId: g.gameId,
          gameCode: g.gameCode,
          date: isoDate,
          timeEst: g.gameDateTimeEst,
          homeTeam: `${g.homeTeam.teamCity} ${g.homeTeam.teamName}`,
