      // Calculate total score: star count * 2000 - total distance
      let totalDist = 0;
      let starCount = 0;
      for (let i = 0; i < schedule.length; i++) {
        if (schedule[i].starPlayer) starCount++;
        if (i > 0) {
          totalDist += dist(schedule[i-1].arenaCity, schedule[i].arenaCity);
        }
      }
      const score = starCount * 3000 - totalDist;
      if (score > bestScore) {
        bestScore = score;
        bestSchedule = {
          schedule,
          starCount,
          totalDistKm: Math.round(totalDist),
          score
        };
      }
    }
  }

  return {
    found: !!bestSchedule,
    bestScore,
    bestSchedule: bestSchedule ? {
      starCount: bestSchedule.starCount,
      totalDistKm: bestSchedule.totalDistKm,
      stops: bestSchedule.schedule.map((g, idx) => ({
        stop: idx + 1,
        date: g.date,
        homeTeam: g.homeTeam,
        awayTeam: g.awayTeam,
        arena: g.arenaName,
        city: g.arenaCity,
        starPlayer: g.starPlayer,
        gameId: g.gameId,
        gameCode: g.gameCode
      }))
    } : null
  };
});

console.log("Solver result found:", routeResult.found);
if (routeResult.found) {
  console.log("Star count:", routeResult.bestSchedule.starCount);
  console.log("Total dist (km):", routeResult.bestSchedule.totalDistKm);
  console.log("Stops count:", routeResult.bestSchedule.stops.length);
}

