      const [m, d, y] = dateOnly.split("/");
      const isoDate = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;

      gd.games.forEach(g => {
        const starTeam = ['LAL', 'GSW', 'SAS'].find(t => t === g.homeTeam.teamTricode || t === g.awayTeam.teamTricode) || null;
        let starPlayer = null;
        if (starTeam === 'LAL') starPlayer = "LeBron James (LAL)";
        else if (starTeam === 'GSW') starPlayer = "Stephen Curry (GSW)";
        else if (starTeam === 'SAS') starPlayer = "Victor Wembanyama (SAS)";

        games.push({
          gameId: g.gameId,
          gameCode: g.gameCode,
          date: isoDate,
          timeEst: g.gameDateTimeEst,
          homeTeam: `${g.homeTeam.teamCity} ${g.homeTeam.teamName}`,
          homeTricode: g.homeTeam.teamTricode,
          awayTeam: `${g.awayTeam.teamCity} ${g.awayTeam.teamName}`,
          awayTricode: g.awayTeam.teamTricode,
          arenaName: g.arenaName,
          arenaCity: g.arenaCity,
          arenaState: g.arenaState,
          starPlayer
        });
      });
    }
  });

  const cityCoords = {
    "Atlanta": [33.757, -84.396],
    "Boston": [42.366, -71.062],
    "Brooklyn": [40.682, -73.975],
    "Charlotte": [35.225, -80.839],
    "Chicago": [41.880, -87.674],
    "Cleveland": [41.496, -81.688],
    "Dallas": [32.790, -96.810],
    "Denver": [39.748, -105.007],
    "Detroit": [42.341, -83.055],
    "San Francisco": [37.768, -122.387],
    "Houston": [29.750, -95.362],
    "Indianapolis": [39.764, -86.155],
    "Inglewood": [33.945, -118.341],
    "Los Angeles": [34.043, -118.267],
    "Memphis": [35.138, -90.050],
    "Miami": [25.781, -80.187],
    "Milwaukee": [43.045, -87.917],
    "Minneapolis": [44.979, -93.276],
    "New Orleans": [29.949, -90.082],
    "New York": [40.750, -73.993],
    "Oklahoma City": [35.463, -97.515],
    "Orlando": [28.539, -81.383],
    "Philadelphia": [39.901, -75.172],
    "Phoenix": [33.445, -112.071],
    "Portland": [45.531, -122.666],
    "Sacramento": [38.580, -121.499],
    "San Antonio": [29.427, -98.437],
    "Toronto": [43.643, -79.379],
