    const pickedTeams = new Set();
    const schedule = [];
    let prevCity = null;

    for (let d = 0; d < dates.length; d++) {
      const date = dates[d];
      const available = gamesByDate[date].filter(g => !pickedTeams.has(g.homeTeam));
      if (available.length === 0) continue;

      const scored = available.map(g => {
        let s = 0;
        if (g.starPlayer) s += 1800;
        if (prevCity) {
          const dKm = dist(prevCity, g.arenaCity);
          s -= dKm * 1.2;
        }
        s += (Math.random() - 0.5) * 500;
        return { g, s };
      });

      scored.sort((a, b) => b.s - a.s);
      const chosen = scored[0].g;
      schedule.push(chosen);
      pickedTeams.add(chosen.homeTeam);
      prevCity = chosen.arenaCity;

      if (pickedTeams.size === 30) break;
    }

    if (pickedTeams.size === 30) {
      let totalDist = 0;
      let starCount = 0;
      for (let i = 0; i < schedule.length; i++) {
        if (schedule[i].starPlayer) starCount++;
        if (i > 0) {
          totalDist += dist(schedule[i-1].arenaCity, schedule[i].arenaCity);
        }
      }
      const score = starCount * 4000 - totalDist;
      if (score > bestScore) {
        bestScore = score;
        bestSchedule = { schedule, starCount, totalDistKm: Math.round(totalDist) };
      }
    }
  }

  return bestSchedule;
});

console.log(`Best schedule found: ${result.starCount} star games, ${result.totalDistKm} km total distance.`);
