const tabId = 103795220;
const regionalSolverResult = await browserjs(tabId, async () => {
  const res = await fetch('https://cdn.nba.com/static/json/staticData/scheduleLeagueV2_1.json');
  const data = await res.json();
  const gameDates = data.leagueSchedule.gameDates;

  const games = [];
  gameDates.forEach(gd => {
    const dStr = gd.gameDate;
    if (dStr.startsWith("03/") || dStr.startsWith("04/")) {
      const dateOnly = dStr.split(" ")[0]; // MM/DD/YYYY
      const [m, d, y] = dateOnly.split("/");
      const isoDate = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;

      gd.games.forEach(g => {
        const starTeam = ['LAL', 'GSW', 'SAS'].find(t => t === g.homeTeam.teamTricode || t === g.awayTeam.teamTricode) || null;
        let starPlayer = null;
        if (starTeam === 'LAL') starPlayer = "LeBron James (LAL)";
        else if (starTeam === 'GSW') starPlayer = "Stephen Curry (GSW)";
        else if (starTeam === 'SAS') starPlayer = "Victor Wembanyama (SAS)";

        games.push({
          gameId: g.gameId,
          gameCode: g.gameCode,
          date: isoDate,
          timeEst: g.gameDateTimeEst,
          homeTeam: `${g.homeTeam.teamCity} ${g.homeTeam.teamName}`,
          homeTricode: g.homeTeam.teamTricode,
          awayTeam: `${g.awayTeam.teamCity} ${g.awayTeam.teamName}`,
          awayTricode: g.awayTeam.teamTricode,
          arenaName: g.arenaName,
          arenaCity: g.arenaCity,
          arenaState: g.arenaState,
          starPlayer
        });
      });
    }
  });

  const cityCoords = {
    "Atlanta": [33.757, -84.396],
    "Boston": [42.366, -71.062],
    "Brooklyn": [40.682, -73.975],
    "Charlotte": [35.225, -80.839],
    "Chicago": [41.880, -87.674],
    "Cleveland": [41.496, -81.688],
    "Dallas": [32.790, -96.810],
    "Denver": [39.748, -105.007],
    "Detroit": [42.341, -83.055],
    "San Francisco": [37.768, -122.387],
    "Houston": [29.750, -95.362],
    "Indianapolis": [39.764, -86.155],
    "Inglewood": [33.945, -118.341],
    "Los Angeles": [34.043, -118.267],
    "Memphis": [35.138, -90.050],
    "Miami": [25.781, -80.187],
    "Milwaukee": [43.045, -87.917],
    "Minneapolis": [44.979, -93.276],
    "New Orleans": [29.949, -90.082],
    "New York": [40.750, -73.993],
    "Oklahoma City": [35.463, -97.515],
    "Orlando": [28.539, -81.383],
    "Philadelphia": [39.901, -75.172],
    "Phoenix": [33.445, -112.071],
    "Portland": [45.531, -122.666],
    "Sacramento": [38.580, -121.499],
    "San Antonio": [29.427, -98.437],
    "Toronto": [43.643, -79.379],
    "Salt Lake City": [40.768, -111.901],
    "Washington": [38.898, -77.020]
  };

  const regions = {
    "Texas & South": ["Houston", "Dallas", "San Antonio", "New Orleans", "Memphis", "Oklahoma City"],
    "Southeast": ["Orlando", "Miami", "Atlanta", "Charlotte"],
    "Midwest": ["Chicago", "Milwaukee", "Minneapolis", "Detroit", "Cleveland", "Indianapolis"],
    "Northeast": ["Washington", "Philadelphia", "Brooklyn", "New York", "Boston", "Toronto"],
    "West": ["San Francisco", "Sacramento", "Portland", "Los Angeles", "Inglewood", "Phoenix", "Salt Lake City", "Denver"]
  };

  const cityToRegion = {};
  for (const [r, cities] of Object.entries(regions)) {
    cities.forEach(c => cityToRegion[c] = r);
  }

  function dist(c1, c2) {
    if (!cityCoords[c1] || !cityCoords[c2]) return 500;
    const [lat1, lon1] = cityCoords[c1];
    const [lat2, lon2] = cityCoords[c2];
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
    return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  }

  const gamesByDate = {};
  games.forEach(g => {
    if (!gamesByDate[g.date]) gamesByDate[g.date] = [];
    gamesByDate[g.date].push(g);
  });
  const dates = Object.keys(gamesByDate).sort();

  let bestSchedule = null;
  let bestScore = -Infinity;

  for (let trial = 0; trial < 150000; trial++) {
    const pickedTeams = new Set();
    const schedule = [];
    let prevCity = null;

    for (let d = 0; d < dates.length; d++) {
      const date = dates[d];
      const available = gamesByDate[date].filter(g => !pickedTeams.has(g.homeTeam));
      if (available.length === 0) continue;

      const scored = available.map(g => {
        let s = 0;
        if (g.starPlayer) s += 1000;
        if (prevCity) {
          const dKm = dist(prevCity, g.arenaCity);
          s -= dKm * 3.0; // strong penalty for long hops
          if (cityToRegion[prevCity] === cityToRegion[g.arenaCity]) {
            s += 800; // bonus for staying in same region
          }
        }
        s += (Math.random() - 0.5) * 400;
        return { g, s };
      });

      scored.sort((a, b) => b.s - a.s);
      const chosen = scored[0].g;
      schedule.push(chosen);
      pickedTeams.add(chosen.homeTeam);
      prevCity = chosen.arenaCity;

      if (pickedTeams.size === 30) break;
    }

    if (pickedTeams.size === 30) {
      let totalDist = 0;
      let starCount = 0;
      let regionSwitches = 0;
      for (let i = 0; i < schedule.length; i++) {
        if (schedule[i].starPlayer) starCount++;
        if (i > 0) {
          totalDist += dist(schedule[i-1].arenaCity, schedule[i].arenaCity);
          if (cityToRegion[schedule[i-1].arenaCity] !== cityToRegion[schedule[i].arenaCity]) {
            regionSwitches++;
          }
        }
      }

      const score = starCount * 2000 - totalDist - regionSwitches * 1000;
      if (score > bestScore) {
        bestScore = score;
        bestSchedule = { schedule, starCount, totalDistKm: Math.round(totalDist), regionSwitches };
      }
    }
  }

  return bestSchedule;
});

console.log(`Regional schedule: ${regionalSolverResult.starCount} star games, ${regionalSolverResult.totalDistKm} km total distance, ${regionalSolverResult.regionSwitches} region switches.`);
regionalSolverResult.schedule.forEach((s, idx) => {
  console.log(`${idx + 1}. [${s.date}] ${s.arenaCity} - ${s.arenaName} | ${s.homeTeam} vs ${s.awayTeam} ${s.starPlayer ? '★ ' + s.starPlayer : ''}`);
});

await write("tmp://schedule_30_regional.json", JSON.stringify(regionalSolverResult.schedule, null, 2));

