const cpTabId = 103795400;

// Click in document area
await tool.mouse({
  tabId: cpTabId,
  action: "left_click",
  coordinate: [500, 300]
});
await tool.press({ tabId: cpTabId, keys: "ControlOrMeta+a" });

// Prepare sample rich text
const testText = "NBA 30-Arena Spring Basketball Trip";
const testHtml = '<h1>NBA 30-Arena Spring Basketball Trip</h1><p>Testing rich text paste</p>';

const pasteSuccess = await browserjs(cpTabId, async (t, h) => {
  try {
    await navigator.clipboard.write([new ClipboardItem({
      "text/plain": new Blob([t], { type: "text/plain" }),
      "text/html": new Blob([h], { type: "text/html" })
    })]);
    return { ok: true };
  } catch(e) {
    return { ok: false, error: e.message };
  }
}, testText, testHtml);

console.log("Clipboard write result:", pasteSuccess);
if (pasteSuccess.ok) {
  const pRes = await tool.press({ tabId: cpTabId, keys: "ControlOrMeta+v" });
  console.log("Press paste result:", pRes);
}
await tool.wait_for({ tabId: cpTabId, condition: "dom_settled", timeout_ms: 1500 });
const sc = await browser.screenshot({ tabId: cpTabId });
console.log("Screenshot URI:", sc.image);

