const schedRaw = await read("tmp://schedule_30.json");
const legsRaw = await read("tmp://legs_30.json");
const hotelsRaw = await read("tmp://hotels_30.json");
const foodRaw = await read("tmp://food_30.json");

const sched = JSON.parse(schedRaw.text);
const legs = JSON.parse(legsRaw.text);
const hotels = JSON.parse(hotelsRaw.text);
const food = JSON.parse(foodRaw.text);

// Build structured markdown document
let md = `# Ultimate NBA 30-Arena Spring Basketball Trip Itinerary

**A Complete Road & Flight Guide to Seeing All 30 NBA Arenas in Spring 2027**

- **Total Stops:** 30 Arenas / 30 NBA Franchises
- **Dates Covered:** March 1, 2027 – April 4, 2027 (35 Days)
- **Marquee Star-Player Showcases:** 11 Games featuring **LeBron James** (LAL), **Stephen Curry** (GSW), and **Victor Wembanyama** (SAS)
- **Routing Strategy:** Regional Clusters connected by efficient domestic flights, utilizing scenic road trip drives where cities are under 4–5 hours apart (e.g., Texas Triangle, Florida Turnpike, Midwest corridor, Northeast Amtrak/I-95 corridor).

---

## Complete 30-Stop Master Itinerary Table

| Stop | Date | Arena & City | Matchup | Star Featured | Travel Leg & Cheapest Mode | Travel Cost | Hotel & Est. Nightly Price | Food Recommendation | Running Total |
|---|---|---|---|---|---|---|---|---|---|
`;

let runningTotal = 0;

for (let i = 0; i < 30; i++) {
  const s = sched[i];
  const l = legs[i];
  const h = hotels[i];
  const f = food[i];

  const travelCost = l.cost || 0;
  const hotelCost = h.price || 0;
  const legTotal = travelCost + hotelCost;
  runningTotal += legTotal;

  const starStr = s.starPlayer ? `★ **${s.starPlayer}**` : "Regular Matchup";
  const travelStr = l.fromCity ? `${l.fromCity} ➔ ${l.toCity} (${l.cheapestMode})` : "Trip Origin (Houston)";
  const hotelStr = `${h.hotel} ($${hotelCost}/nt)`;
  const foodStr = `${f.restaurant} (${f.specialty.split('(')[0].trim()})`;

  md += `| **#${i + 1}** | ${s.date} | **${s.arenaName}**<br>${s.arenaCity}, ${s.arenaState} | ${s.homeTeam} vs.<br>${s.awayTeam} | ${starStr} | ${travelStr}<br>_${l.details}_ | $${travelCost} | ${hotelStr} | ${foodStr} | **$${runningTotal}** |\n`;
}

md += `\n---

## Trip Financial & Logistical Summary

- **Total Estimated Travel Cost (Flights & Driving Gas/Tolls):** $${legs.reduce((a, b) => a + (b.cost || 0), 0)}
- **Total Estimated Lodging Cost (30 Nights):** $${hotels.reduce((a, b) => a + (b.price || 0), 0)}
- **Total Estimated Core Trip Cost (Travel + Hotels):** **$${runningTotal}**
- _Note:_ Food and game tickets vary by tier (budget ~$50–$80/day for dining, and marquee matchups featuring LeBron, Curry, and Wemby will have higher secondary market ticket prices).

---

## Key Marquee Player Highlights (11 Games)
1. **Stop 1 (Houston, Mar 1):** Rockets vs. Warriors — Stephen Curry (GSW) on the road.
2. **Stop 2 (Dallas, Mar 2):** Mavericks vs. Warriors — Stephen Curry (GSW) at American Airlines Center.
3. **Stop 3 (Denver, Mar 3):** Nuggets vs. Spurs — Victor Wembanyama (SAS) visiting Ball Arena.
4. **Stop 4 (San Francisco, Mar 4):** Warriors vs. Wizards — Stephen Curry (GSW) at home in Chase Center.
5. **Stop 6 (Los Angeles, Mar 6):** Lakers vs. Thunder — LeBron James (LAL) at home in Crypto.com Arena.
6. **Stop 7 (San Antonio, Mar 7):** Spurs vs. Knicks — Victor Wembanyama (SAS) at home in Frost Bank Center.
7. **Stop 14 (Oklahoma City, Mar 14):** Thunder vs. Spurs — Victor Wembanyama (SAS) at Paycom Center.
8. **Stop 21 (Philadelphia, Mar 21):** 76ers vs. Spurs — Victor Wembanyama (SAS) at Xfinity Mobile Arena.
9. **Stop 24 (Boston, Mar 24):** Celtics vs. Spurs — Victor Wembanyama (SAS) at historic TD Garden.
10. **Stop 25 (Indianapolis, Mar 25):** Pacers vs. Spurs — Victor Wembanyama (SAS) at Gainbridge Fieldhouse.
11. **Stop 29 (Inglewood, Mar 29):** Clippers vs. Spurs — Victor Wembanyama (SAS) at the brand new Intuit Dome.

---

## Detailed Stop-by-Stop Breakdown

`;

for (let i = 0; i < 30; i++) {
  const s = sched[i];
  const l = legs[i];
  const h = hotels[i];
  const f = food[i];

  md += `### Stop ${i + 1}: ${s.arenaCity}, ${s.arenaState} — ${s.arenaName}
- **Date:** ${s.date} (Game ID: ${s.gameId}, Code: ${s.gameCode})
- **Matchup:** ${s.homeTeam} vs. ${s.awayTeam}
- **Featured Star:** ${s.starPlayer ? s.starPlayer : "None (Team showcase)"}
- **Travel Leg:** ${l.fromCity ? `${l.fromCity} to ${l.toCity}` : "Start of Trip"}
  - **Cheapest Practical Mode:** ${l.cheapestMode} (Est. Cost: $${l.cost})
  - **Routing Details:** ${l.details}
- **Recommended Hotel:** ${h.hotel} (~$${h.price}/night, ${h.distance})
- **Local Food Highlight:** ${f.restaurant} — ${f.specialty}
\n`;
}

await write("tmp://itinerary_markdown.md", md);
console.log("Generated itinerary markdown, characters:", md.length);

