// Click inside the CodeMirror editor on the left side
await tool.mouse({
  tabId: cTabId,
  action: "left_click",
  coordinate: [200, 300]
});

// Select all existing content
await tool.press({
  tabId: cTabId,
  keys: "ControlOrMeta+a"
});

// Read the markdown content
const mdRaw = await read("tmp://itinerary_markdown.md");
const mdText = mdRaw.text;

// Write text to clipboard
const clipRes = await browserjs(cTabId, async (text) => {
  try {
    await navigator.clipboard.writeText(text);
    return { ok: true };
  } catch(e) {
    return { ok: false, error: e.message };
  }
}, mdText);
console.log("Clipboard writeText result:", clipRes);

if (clipRes.ok) {
  const pasteRes = await tool.press({
    tabId: cTabId,
    keys: "ControlOrMeta+v"
  });
  console.log("Press paste result:", pasteRes);
}

await tool.wait_for({ tabId: cTabId, condition: "dom_settled", timeout_ms: 3000 });
const sc = await browser.screenshot({ tabId: cTabId });
console.log("Screenshot after paste:", sc.image);

